/* LOGIN-01 — Tarjeta de acceso centrada sobre el azul de marca. Sin shell. */

.page {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px;
  background: var(--bw-deep-steel-darkest);
  box-sizing: border-box;
}

.card {
  width: 100%;
  max-width: 400px;
  padding: var(--bw-pad-panel);
  background: var(--bw-warm-cream);
  border: 1px solid var(--bw-line-steel);
  border-radius: var(--bw-radius);
  box-sizing: border-box;
}

.eyebrow {
  margin: 0;
  font-family: var(--bw-font-body);
  font-size: var(--bw-size-eyebrow);
  letter-spacing: var(--bw-ls-eyebrow);
  text-transform: uppercase;
  color: var(--bw-brass);
}

.title {
  margin: 6px 0 0;
  font-family: var(--bw-font-title);
  font-size: var(--bw-size-title);
  line-height: 1.2;
  letter-spacing: var(--bw-ls-title);
  color: var(--bw-deep-steel);
}

.form {
  display: flex;
  flex-direction: column;
  gap: 18px;
  margin-top: 28px;
}

.field {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.label {
  font-family: var(--bw-font-body);
  font-size: var(--bw-size-label);
  letter-spacing: var(--bw-ls-label);
  color: var(--bw-text-secondary);
}

.input {
  width: 100%;
  padding: var(--bw-pad-input);
  font-family: var(--bw-font-body);
  font-size: var(--bw-size-input);
  color: var(--bw-input-text);
  background: var(--bw-cold-white);
  border: 1px solid var(--bw-line-steel-strong);
  border-radius: var(--bw-radius);
  box-sizing: border-box;
  outline: none;
}

.input::placeholder {
  color: var(--bw-input-placeholder);
}

.input:focus {
  border-color: var(--bw-calibration-blue);
  box-shadow: var(--bw-focus-halo);
}

.input:disabled {
  opacity: 0.65;
}

.encryptHint {
  margin: 0;
  font-family: var(--bw-font-body);
  font-size: var(--bw-size-hint);
  letter-spacing: var(--bw-ls-hint);
  line-height: 1.5;
  color: var(--bw-text-secondary);
}

.error {
  margin: 0;
  padding: var(--bw-pad-input);
  font-family: var(--bw-font-body);
  font-size: var(--bw-size-input);
  line-height: 1.4;
  color: var(--bw-error-text);
  background: var(--bw-sensitive-bg);
  border: 1px solid var(--bw-badge-danger-border);
  border-radius: var(--bw-radius);
}

.submit {
  width: 100%;
  padding: var(--bw-pad-input);
  font-family: var(--bw-font-body);
  font-size: var(--bw-size-input);
  font-weight: 600;
  color: var(--bw-warm-cream);
  background: var(--bw-calibration-blue);
  border: 1px solid var(--bw-calibration-blue);
  border-radius: var(--bw-radius);
  cursor: pointer;
}

.submit:hover:not(:disabled) {
  background: var(--bw-primary-dark);
  border-color: var(--bw-primary-dark);
}

.submit:focus-visible {
  outline: none;
  box-shadow: var(--bw-focus-halo);
}

.submit:disabled {
  background: var(--bw-surface-mist);
  color: var(--bw-hint-steel);
  border-color: var(--bw-line-steel);
  cursor: not-allowed;
}

@media (max-width: 479px) {
  .page {
    padding: 16px;
  }

  .card {
    padding: 24px;
  }
}

